import{_ as t,o as e,c as a,a4 as u}from"./chunks/framework.9tZL7ZIQ.js";const s=JSON.parse('{"title":"1972年 · 黄金时代序章","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1972年.md","filePath":"05_quotes/by-year/1972年.md"}'),q={name:"05_quotes/by-year/1972年.md"};function l(r,o,c,b,i,p){return e(),a("div",null,[...o[0]||(o[0]=[u('<h1 id="_1972年-·-黄金时代序章" tabindex="-1">1972年 · 黄金时代序章 <a class="header-anchor" href="#_1972年-·-黄金时代序章" aria-label="Permalink to &quot;1972年 · 黄金时代序章&quot;">​</a></h1><blockquote><p>&quot;三位公司的创始人都是主要出售方，获得了大额现金对价，但仍以不减的热情与创造力继续经营，推动业绩再创新高。&quot;——巴菲特（41岁）</p></blockquote><p>本页收录1972年致股东信中的经典语录。伯克希尔营业收益达到期初股东权益的19.8%，创历史新高！Jack Ringwalt、Gene Abegg、Vic Raab三位创始人全面爆发。巴菲特在这一年正式宣告：资本重新配置战略成功，伯克希尔已从一家困境纺织厂，蜕变为多元控股平台。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;1965年5月我们正式接手伯克希尔。八年后，营业收益达1111万美元，远高于若公司仍将全部资源投入纺织业务所能实现的收益。&quot;</p></blockquote><blockquote><p>&quot;三位公司的创始人都是主要出售方，获得了大额现金对价，但仍以不减的热情与创造力继续经营，推动业绩再创新高。&quot;</p></blockquote><blockquote><p>&quot;以资本回报率衡量，他们在约20%资本回报率的水平上超越了IBM、通用电气、通用汽车、宝洁、杜邦、Control Data、惠普等知名公司。&quot;</p></blockquote><blockquote><p>&quot;市场价格对我们评估控股权益的估值完全无关。我们在1967年底以25的估值对应市场约20，在1968年底以31对应市场约37。无论市场是15和50，我们都会做同样的事。&quot;</p></blockquote><blockquote><p>&quot;价格是你支付的，价值是你得到的。&quot;</p></blockquote><blockquote><p>&quot;如果今年利润没有如此暴涨，我们未来五年的前景或许会更好。&quot;（论超高承保利润）</p></blockquote><blockquote><p>&quot;以盈利为前提承保，费率基于长期预期而非短期乐观。这一策略过去虽曾导致规模阶段性下滑，但长期效果优异。&quot;</p></blockquote><blockquote><p>&quot;我们计划在费率持续恶化的背景下，储备充足的资金，以承接届时将出现的、定价合理的大规模业务。&quot;</p></blockquote><blockquote><p>&quot;尽管纺织行业整体盈利水平仍是决定纺织业务收益的首要因素，但公司在行业内的相对地位已明显提升。&quot;</p></blockquote><blockquote><p>&quot;我们将继续寻找现有业务的合理延伸机会，同时发掘新业务，以高效运用资本。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><h2 id="_1972年是伯克希尔的标志性年份-营业收益1111万美元-roe达19-8-远超1964年的10-水平。股东权益从1964年的2214万增至6200万-年均复合增长16-8-且全程不增发新股、不大量举债。巴菲特在年报中第一次系统性总结了三位收购的创始人型企业家——他们-现金出售后仍全力投入-的故事-成为伯克希尔此后50年收购文化的原型模板。" tabindex="-1">1972年是伯克希尔的标志性年份：营业收益1111万美元，ROE达19.8%，远超1964年的10%水平。股东权益从1964年的2214万增至6200万，年均复合增长16.8%，且全程不增发新股、不大量举债。巴菲特在年报中第一次系统性总结了三位收购的创始人型企业家——他们&quot;现金出售后仍全力投入&quot;的故事，成为伯克希尔此后50年收购文化的原型模板。 <a class="header-anchor" href="#_1972年是伯克希尔的标志性年份-营业收益1111万美元-roe达19-8-远超1964年的10-水平。股东权益从1964年的2214万增至6200万-年均复合增长16-8-且全程不增发新股、不大量举债。巴菲特在年报中第一次系统性总结了三位收购的创始人型企业家——他们-现金出售后仍全力投入-的故事-成为伯克希尔此后50年收购文化的原型模板。" aria-label="Permalink to &quot;1972年是伯克希尔的标志性年份：营业收益1111万美元，ROE达19.8%，远超1964年的10%水平。股东权益从1964年的2214万增至6200万，年均复合增长16.8%，且全程不增发新股、不大量举债。巴菲特在年报中第一次系统性总结了三位收购的创始人型企业家——他们&quot;现金出售后仍全力投入&quot;的故事，成为伯克希尔此后50年收购文化的原型模板。&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1972年/翻译">/01_letters/1972年/翻译</a></li></ul>',20)])])}const _=t(q,[["render",l]]);export{s as __pageData,_ as default};
